-- =====================================================================
-- Lojas cadastradas pelo guia — RODADA 5
-- As de maior conceito no Google em Alfenas (nota pesada pelo número de
-- avaliações), só com fotos publicadas pelo próprio dono e endereço,
-- telefone e horário completos, tudo do perfil oficial.
-- =====================================================================
-- Saem do guia, a pedido (13/10/2026): Supermercado São Paulo e Unissul.
-- Apagar a conta de login leva junto o anúncio e o cadastro (on delete
-- cascade). O segundo delete cobre o caso de a conta já não existir.
delete from auth.users
 where email in ('supermercadosaopaulo@comercioalfenas.com.br',
                 'unissul@comercioalfenas.com.br');

delete from public.anuncios
 where titulo in ('Supermercado São Paulo', 'Unissul Supermercados');

